{
  "strategy_id": "agent_practical",
  "strategy_title": "RAG 기반 가상 규정 검증 시제품 개발 로드맵",
  "summary": "사용자의 2 주 3 시간/주 예산과 Python 기초 경험, LLM/RAG 초보 상태를 고려하여, 검색된 규정 문서 (인재개발규정, 직제규정) 와 RAG 관련 무료 코스를 활용하여 '가상 규정 3 건에서 질문 5 건의 근거 표시 및 근거 없는 질문 구분'을 수행하는 시제품을 개발하는 로드맵입니다. 승인되지 않은 규정 자료는 사용 불가로 처리하며, 비용이 없는 Microsoft Learn 코스를 중심으로 학습과 실습을 병행합니다.",
  "project_goal": "검색된 규정 문서 (인재개발규정, 직제규정) 를 활용하여, 주어진 가상 규정 3 건에 대한 질문 5 건 중 근거가 있는 질문은 해당 규정을 인용하고, 근거 없는 질문은 구분하여 표시하는 최소 기능 RAG 시제품을 완성합니다.",
  "total_duration_weeks": 2,
  "roadmap_flow": [
    {
      "step": 1,
      "title": "RAG 아키텍처 설계 및 검색 데이터 준비",
      "duration_weeks": 1,
      "focus": "검색된 규정 문서 (인재개발규정, 직제규정) 를 파싱하여 벡터 데이터베이스에 저장하고, 검색 엔진 연결 (RAG) 로직 구현",
      "activities": [
        "Python 기반 RAG 파이프라인 설계 (문서 파싱, 벡터화, 검색 로직)",
        "검색된 '인재개발규정' 및 '직제규정' 텍스트를 벡터 DB에 인덱싱",
        "가상 규정 3 건과 질문 5 건을 입력 데이터로 정의"
      ],
      "deliverables": [
        "RAG 시제품 소스 코드 (파싱, 벡터화, 검색 모듈)",
        "벡터 데이터베이스에 저장된 규정 문서 인덱스"
      ],
      "completion_criteria": "검색된 규정 2 건이 벡터 DB에 정상 인덱싱되고, 질문 입력 시 관련 규정 텍스트를 검색할 수 있는 로직이 구현됨"
    },
    {
      "step": 2,
      "title": "LLM 통합 및 근거 추출/구분 로직 구현",
      "duration_weeks": 1,
      "focus": "검색된 결과를 LLM에 전달하여 답변 생성하고, '근거 표시' 및 '근거 없음 구분' 기능을 구현",
      "activities": [
        "검색 결과를 LLM 프롬프트에 포함하는 시스템 설계",
        "LLM에게 '근거 있는 질문은 규정을 인용하고, 근거 없는 질문은 구분'하도록 프롬프트 작성",
        "시제품 실행을 통해 5 건의 질문 처리 결과 검증"
      ],
      "deliverables": [
        "LLM 통합 RAG 시제품 실행 스크립트",
        "5 건의 가상 질문에 대한 처리 결과 로그 (근거 유무 구분)"
      ],
      "completion_criteria": "5 건의 가상 질문 중 근거 있는 질문은 검색된 규정 (인재개발규정, 직제규정) 을 인용하고, 근거 없는 질문은 '근거 없음'으로 구분하여 출력됨"
    }
  ],
  "milestones": [
    {
      "phase": 1,
      "phase_name": "데이터 준비 및 검색 로직 완성",
      "duration_weeks": 1,
      "focus_goal": "검색된 규정 문서 (인재개발규정, 직제규정) 를 벡터 DB에 저장하고 검색 가능하게 만드는 것",
      "key_actions": [
        "인재개발규정 > 제3장 > 제18조 등 검색된 텍스트 파싱",
        "직제규정 > 별표4 > AI본부 등 검색된 텍스트 파싱",
        "파싱된 데이터를 벡터 DB에 저장"
      ],
      "deliverables": [
        "인덱싱된 규정 문서 데이터"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_41fd82f2348f"
        },
        {
          "course_id": "MS_df219eb945ff"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 2,
      "phase_name": "LLM 기반 근거 추출 및 구분 기능 완성",
      "duration_weeks": 1,
      "focus_goal": "검색 결과를 바탕으로 LLM이 근거 있는 질문은 규정을 인용하고, 근거 없는 질문은 구분하는 기능 구현",
      "key_actions": [
        "검색 결과와 LLM 프롬프트 구성 (근거 표시/구분 지시)",
        "가상 규정 3 건에 대한 5 건의 질문 처리 실행",
        "처리 결과 검증 및 수정"
      ],
      "deliverables": [
        "5 건의 가상 질문에 대한 처리 결과 (근거 유무 구분)"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_d1f2eed6c592"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    }
  ],
  "regulation_citations": []
}
